    const buf = new Float32Array(N);
    for (let i = 0; i < N; i++) {
      buf[i] = input[i] + (i >= d ? buf[i - d] * fb : 0);
      out[i] += buf[i] * 0.25;
    }
  }
  return out;
}

export function synthesize() {
  const dry = new Float32Array(N);
  const wet = new Float32Array(N);
  const panL = new Float32Array(N);
